// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.contextimport java.util.Locale/** * NOUS — User context (identity + preferences). * * Built from [com.roshan.persona.datastore.NousPreferences] + on-device learning * (Module 8 — Preference Learning). All data stays on device. * * Privacy contract: *   - [userId] is an anonymous UUID, NEVER PII *   - [displayName] is user-typed, NEVER sent to cloud (used only for local *     persona system prompt substitution) *   - [monthlyLlmSpentUsd] is tracked locally, NEVER synced to cloud */data class UserContext(    /** Anonymous UUID — generated on first launch, never correlated to PII. */    val userId: String,    /** User-typed name (e.g., "Roshan"). Used in persona prompts. Never cloud. */    val displayName: String?,    /** User's preferred locale (drives STT, TTS, response language). */    val preferredLanguage: Locale,    /** User's preferred response length. */    val preferredResponseLength: ResponseLength,    /** Per-skill preference weights (0.0-1.0). Higher = preferred. */    val skillPreferences: Map<String, SkillPreference>,    /** Privacy settings — what's enabled. */    val privacySettings: PrivacySettings,    /** Monthly LLM budget cap in USD (user-set, default $5). */    val monthlyLlmBudgetUsd: Float,    /** Running monthly LLM spend (resets on 1st of each month). */    val monthlyLlmSpentUsd: Float,)/** Per-skill preference. */data class SkillPreference(    val skillId: String,    val weight: Float,    val lastUsedEpochMs: Long,    val successRate: Float,    val useCount: Long,)/** User's preferred response verbosity. */enum class ResponseLength { TERSE, BALANCED, VERBOSE }/** * Privacy settings — what's enabled (all default OFF per ADR 0011). * * @see <a href="docs/adr/0011-maximum-privacy-default.md">ADR 0011</a> */data class PrivacySettings(    val cloudLlmEnabled: Boolean = false,    val crashReportingEnabled: Boolean = false,    val anonymousTelemetryEnabled: Boolean = false,    val wakeWordEnabled: Boolean = false,    val voiceBiometricsEnabled: Boolean = false,    val ambientAwarenessEnabled: Boolean = false,    val multiDeviceSyncEnabled: Boolean = false,)